  `create_time` int(10) UNSIGNED NOT NULL COMMENT '创建时间',
  `title` varchar(255) NOT NULL DEFAULT '' COMMENT '活动标题',
  `image` varchar(255) NOT NULL DEFAULT '' COMMENT '活动图片',
  `country_id` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '国家ID, 0 表示所有国家',
  `is_app_show` tinyint(3) UNSIGNED NOT NULL DEFAULT 1 COMMENT '类型：1 是, 2 否'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='活动配置表' ROW_FORMAT=DYNAMIC;

