--
-- Table structure for table `yh_order`
--

CREATE TABLE `yh_order` (
  `id` int(10) UNSIGNED NOT NULL,
  `order_no` varchar(64) NOT NULL COMMENT '订单号',
  `user_id` int(10) UNSIGNED NOT NULL COMMENT '用户ID',
  `country_id` int(10) UNSIGNED NOT NULL COMMENT '国家ID',
  `batch_id` int(10) UNSIGNED NOT NULL COMMENT '汇率批次ID',
  `wallet_type` tinyint(3) NOT NULL DEFAULT 1 COMMENT '1.国家货币钱包 2.USDT钱包',
  `status` tinyint(3) UNSIGNED NOT NULL DEFAULT 1 COMMENT '订单状态：1.待处理 2.成功 3.失败 4.部分成功',
  `user_card_id` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户选择卡类型',
  `user_facevalue` decimal(10,2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '用户填写卡面值',
  `user_memo` varchar(512) NOT NULL DEFAULT '' COMMENT '用户其他备注',
  `whatapp_code` varchar(20) NOT NULL DEFAULT '' COMMENT '关联WhatsApp编号',
  `chat_whatsapp` varchar(30) NOT NULL DEFAULT '' COMMENT '用户聊天的whatsapp账号',
  `input_time` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '订单录入时间',
  `input_admin_id` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '订单录入后台人员ID',
  `deal_start_time` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '后台处理开始时间',
  `deal_end_time` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '后台处理结束时间',
  `deal_status` tinyint(3) UNSIGNED NOT NULL DEFAULT 1 COMMENT '后台处理状态 1.待处理 2.处理中 3.处理完成 4.待自动充值 5.自动充值异常，6.自动充值中, 7.待审核, 8.待用户确认, 9.争议中',
  `deal_admin_id` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '处理员工ID',
  `deal_memo` varchar(512) NOT NULL DEFAULT '' COMMENT '处理备注',
  `card_cnt` tinyint(3) UNSIGNED NOT NULL DEFAULT 1 COMMENT '订单包含卡密数量',
  `purchase_amount` decimal(10,2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '订单总收卡金额（国家货币单位）',
  `purchase_usd` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '收卡USD,收卡金额除以当时国家汇率',
  `sellout_amount` decimal(10,2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '订单总售卡金额（人民币）',
  `facevalue` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '订单面值',
  `coupon_code` varchar(10) NOT NULL DEFAULT '' COMMENT '优惠码',
  `coupon_amount` decimal(10,2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '优惠码返利金额',
  `withdrawal_code` char(10) DEFAULT NULL COMMENT '提现码',
  `device_no` varchar(64) NOT NULL DEFAULT '' COMMENT '下单设备号',
  `is_reward` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已经供应商提成完成 -1待处理 0 无需处理 1已处理',
  `channel_type` tinyint(1) NOT NULL DEFAULT 1 COMMENT '订单创建渠道：1 移动端创建，2 后台创建, 3 web官网, 4 wap, 5 线下WhatsApp, 6 官方WhatsApp',
  `create_time` int(10) UNSIGNED NOT NULL COMMENT '订单创建时间',
  `is_read` tinyint(1) NOT NULL DEFAULT 0 COMMENT '异常订单时 是否阅读：0 默认，1 已读',
  `brand_id` int(11) NOT NULL DEFAULT 1 COMMENT '品牌编号',
  `crm_notice` int(11) NOT NULL DEFAULT 1 COMMENT 'crm 订单处理通知：1 未通知，2 已通知',
  `demand_id` int(11) NOT NULL DEFAULT 0 COMMENT '需求ID',
  `m_user_id` int(11) NOT NULL DEFAULT 0 COMMENT '马甲用户id',
  `cs_id` int(11) NOT NULL DEFAULT 0 COMMENT '客服ID',
  `cs_name` varchar(64) NOT NULL DEFAULT '' COMMENT '客服名称',
  `cs_is_original` tinyint(1) NOT NULL DEFAULT 0 COMMENT '下单客服是否是开发客服',
  `channel_id` int(11) NOT NULL DEFAULT 0 COMMENT '客服系统渠道ID',
  `platform_fee_rate` decimal(10,2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '平台手续费比例',
  `plafform_fee` decimal(10,2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '平台手续费',
  `update_time` int(11) NOT NULL DEFAULT 0 COMMENT '更新时间',
  `is_compensated` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否超时赔付 1赔付 0未赔付',
  `delay_finish_time` int(10) NOT NULL DEFAULT 0 COMMENT '延迟完成时间'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='订单表' ROW_FORMAT=DYNAMIC;

