  `user_id` int(10) NOT NULL COMMENT '用户ID',
  `type` tinyint(3) NOT NULL COMMENT '订单类型 1虚拟权益 2实体商品',
  `address` varchar(255) DEFAULT NULL COMMENT '地址',
  `status` tinyint(3) NOT NULL COMMENT '状态 0待处理 1待发货 2已发货 3完成',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `brand_id` tinyint(3) NOT NULL DEFAULT 1 COMMENT '平台ID',
  `delivery_time` datetime DEFAULT NULL COMMENT '发货时间',
  `end_time` datetime DEFAULT NULL COMMENT '完成时间',
  `recipient` varchar(255) NOT NULL DEFAULT '' COMMENT '收件人',
  `phone` varchar(50) NOT NULL DEFAULT '' COMMENT '手机号'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC;

-- --------------------------------------------------------

--
-- Table structure for table `yh_pop`
--

CREATE TABLE `yh_pop` (
  `id` int(11) NOT NULL,
  `image` varchar(255) NOT NULL COMMENT '图片地址',
  `url` varchar(255) NOT NULL DEFAULT '' COMMENT '点击图片后跳转的地址',
  `jump_type` tinyint(1) NOT NULL DEFAULT 1 COMMENT '跳转类型: 1 APP内链接 2 外链接',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '弹窗状态：0 禁用，1 启用',
  `brand_id` int(11) NOT NULL DEFAULT 1 COMMENT '品牌ID',
  `condition` tinyint(4) NOT NULL DEFAULT 0 COMMENT '弹窗条件：0 重启程序触发，1 注册成功触发，2 订单创建成功触发，3提现发起成功触发',
  `range` tinyint(1) NOT NULL DEFAULT 0 COMMENT '弹窗范围：0 全部用户，1 未绑定whatsapp的用户 2未注册设备',
  `frequency` tinyint(4) NOT NULL COMMENT '单次 0 每次重启 1 1天/次 23天/次 3 7天/次 4 30天/次 5',
  `start_time` int(11) NOT NULL COMMENT '开始时间',
  `end_time` int(11) NOT NULL COMMENT '结束时间',
  `create_time` int(11) NOT NULL,
  `type` tinyint(1) NOT NULL DEFAULT 1 COMMENT '1:正常  2:优惠券  3:vip'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

-- --------------------------------------------------------

--
-- Table structure for table `yh_pop_log`
--

CREATE TABLE `yh_pop_log` (
  `id` int(11) NOT NULL,
  `brand_id` int(11) NOT NULL DEFAULT 0 COMMENT '品牌ID',
  `user_id` int(11) NOT NULL DEFAULT 0 COMMENT '用户ID',
  `device_no` varchar(100) NOT NULL DEFAULT '' COMMENT '设备号',
  `pop_id` int(11) NOT NULL DEFAULT 0 COMMENT '弹窗ID',
  `create_time` int(11) NOT NULL COMMENT '创建事件',
  `remark` varchar(255) NOT NULL DEFAULT '' COMMENT '备注',
  `type` tinyint(3) NOT NULL DEFAULT 1 COMMENT '1 用户主动触发 2后台推送触发',
  `status` tinyint(3) NOT NULL DEFAULT 1 COMMENT '1 已读  2未读'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='弹窗记录表' ROW_FORMAT=DYNAMIC;

-- --------------------------------------------------------

--
-- Table structure for table `yh_prize_log`
--

CREATE TABLE `yh_prize_log` (
  `id` int(10) UNSIGNED NOT NULL COMMENT 'ID',
  `activity_no` varchar(32) NOT NULL COMMENT '活动编号',
  `activity_type` tinyint(3) NOT NULL COMMENT '活动类型 1签到活动 2抽奖活动 3商城兑换 4排行活动',
  `user_id` int(10) NOT NULL COMMENT '用户ID',
  `prize_type` tinyint(3) NOT NULL COMMENT '奖励类型',
  `prize_value` varchar(64) NOT NULL COMMENT '奖励值',
  `status` tinyint(3) NOT NULL COMMENT '状态 0待发放 1已发放',
  `create_time` int(10) UNSIGNED NOT NULL COMMENT '创建时间',
  `update_time` int(10) UNSIGNED NOT NULL COMMENT '更新时间',
  `brand_id` tinyint(3) NOT NULL DEFAULT 1 COMMENT '平台ID'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='活动奖励记录表' ROW_FORMAT=DYNAMIC;

-- --------------------------------------------------------

--
-- Table structure for table `yh_purchase_goods`
--

CREATE TABLE `yh_purchase_goods` (
  `id` int(10) UNSIGNED NOT NULL COMMENT 'id',
  `name` varchar(128) NOT NULL COMMENT '商品名称',
  `desc` text DEFAULT NULL COMMENT '商品介绍',
  `price` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '价格',
  `img` varchar(255) NOT NULL DEFAULT '' COMMENT '图片',
  `currency` varchar(4) NOT NULL DEFAULT '$' COMMENT '货币',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `quantity` int(10) NOT NULL DEFAULT 0 COMMENT '库存',
  `status` tinyint(3) NOT NULL DEFAULT 1 COMMENT '状态 0禁用 1开启',
  `brand_id` tinyint(3) NOT NULL DEFAULT 1 COMMENT '平台ID'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='马甲商品表' ROW_FORMAT=DYNAMIC;

-- --------------------------------------------------------

--
-- Table structure for table `yh_purchase_order`
--

CREATE TABLE `yh_purchase_order` (
  `id` int(10) UNSIGNED NOT NULL COMMENT 'ID',
  `purchase_no` varchar(64) NOT NULL COMMENT '购买订单号',
  `user_id` int(10) NOT NULL COMMENT '用户ID',
  `country_id` int(10) NOT NULL COMMENT '国家ID',
  `status` tinyint(3) NOT NULL COMMENT '状态 1.待处理 2.成功 3.失败',
  `deal_status` tinyint(3) NOT NULL DEFAULT 0 COMMENT '处理状态 0.待处理 1.待发货 2.已发货 3.退货',
  `goods_id` int(10) NOT NULL COMMENT '商品',
  `num` int(11) NOT NULL DEFAULT 0 COMMENT '商品数量',
  `email` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '邮箱',
  `unit_price` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '单价',
  `total_price` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '总价',
  `currency` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '$' COMMENT '货币',
  `brand_id` tinyint(3) NOT NULL DEFAULT 1 COMMENT '平台ID',
  `create_time` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建时间'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='购买订单表' ROW_FORMAT=DYNAMIC;

-- --------------------------------------------------------

--
-- Table structure for table `yh_push_device`
--

CREATE TABLE `yh_push_device` (
  `id` int(10) UNSIGNED NOT NULL,
  `device_token` varchar(512) NOT NULL DEFAULT '' COMMENT '第三方推送device_token',
  `is_active` tinyint(3) UNSIGNED NOT NULL DEFAULT 1 COMMENT '是否有效 1.有效 2.失效',
  `device_no` varchar(64) NOT NULL DEFAULT '' COMMENT 'app设备号',
  `os_type` varchar(100) NOT NULL DEFAULT '' COMMENT '设备类型',
  `user_id` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户ID',
  `country_id` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户国家ID',
  `active_time` int(10) UNSIGNED NOT NULL COMMENT '上次活跃时间',
  `create_time` int(10) UNSIGNED NOT NULL,
  `brand_id` int(11) NOT NULL DEFAULT 1 COMMENT '品牌编号'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='推送devicetoken表' ROW_FORMAT=DYNAMIC;

-- --------------------------------------------------------

--
-- Table structure for table `yh_push_devicelog`
--

CREATE TABLE `yh_push_devicelog` (
  `id` int(10) UNSIGNED NOT NULL,
  `push_id` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `devicetoken_ids` text NOT NULL COMMENT '设备devicetoken ID',
  `is_send` tinyint(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否发送成功 0 发送中 1.成功 2.失败',
  `total_cnt` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '总设备数',
  `success_cnt` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '成功个数',
  `fail_cnt` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '失败个数',
  `fail_reason` varchar(1024) NOT NULL DEFAULT '' COMMENT '失败原因',
  `create_time` int(10) UNSIGNED NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='设备推送记录表' ROW_FORMAT=DYNAMIC;

-- --------------------------------------------------------

--
-- Table structure for table `yh_push_record`
--

CREATE TABLE `yh_push_record` (
  `id` int(10) UNSIGNED NOT NULL,
  `brand_id` int(11) NOT NULL DEFAULT 1 COMMENT '平台ID',
  `title` varchar(512) NOT NULL COMMENT '标题',
  `subject` varchar(1024) NOT NULL COMMENT '摘要',
  `is_mail` tinyint(3) UNSIGNED NOT NULL DEFAULT 1 COMMENT '是否发送邮件 1.不发送 2.发送',
  `mail_title` varchar(512) NOT NULL DEFAULT '' COMMENT '邮件标题',
  `mail_content` text DEFAULT NULL COMMENT '邮件内容',
  `user_tags` varchar(128) NOT NULL COMMENT '用户标签 all:所有 list:push_user列表',
  `coupon_id` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '优惠券活动id',
  `is_all` tinyint(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '1 是否全部用户',
  `open_status` tinyint(3) UNSIGNED NOT NULL COMMENT '1.待发布 2.已发布',
  `push_status` tinyint(3) UNSIGNED NOT NULL DEFAULT 1 COMMENT '1.待推送 2.推送中 3.推送完成',
  `push_time` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '推送事件',
  `country_id` int(10) UNSIGNED NOT NULL COMMENT '国家ID',
  `action` varchar(20) NOT NULL COMMENT '点击事件：web,app_home,app_finder',
  `params` varchar(255) NOT NULL DEFAULT '' COMMENT '点击事件参数',
  `activity_id` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '关联活动ID',
  `type` tinyint(3) NOT NULL DEFAULT 1 COMMENT '推送类型 1活动推送 2汇率提醒 3优惠码',
  `create_time` int(10) UNSIGNED NOT NULL COMMENT '添加时间'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='APP推送记录表' ROW_FORMAT=DYNAMIC;

-- --------------------------------------------------------

