  `user_id` int(10) UNSIGNED NOT NULL COMMENT '用户ID'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='推送选定用户列表' ROW_FORMAT=DYNAMIC;

