-- Table structure for table `yh_qrcode_source`
--

CREATE TABLE `yh_qrcode_source` (
  `id` int(11) NOT NULL,
  `qrcode_scale` int(11) NOT NULL DEFAULT 0,
  `qrcode_x` int(11) NOT NULL DEFAULT 0,
  `qrcode_y` int(11) NOT NULL DEFAULT 0,
  `brand_id` int(11) NOT NULL DEFAULT 1,
  `name` varchar(45) NOT NULL DEFAULT '',
  `logo_name` varchar(45) NOT NULL DEFAULT '',
  `logo_x` int(11) NOT NULL DEFAULT 0,
  `logo_y` int(11) NOT NULL DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC;

