--
-- Table structure for table `yh_rank_activity`
--

CREATE TABLE `yh_rank_activity` (
  `id` int(10) UNSIGNED NOT NULL COMMENT 'ID',
  `activity_no` varchar(32) NOT NULL COMMENT '活动编号',
  `name` varchar(64) NOT NULL COMMENT '活动名称',
  `desc` varchar(64) NOT NULL COMMENT '活动中文备注',
  `link` varchar(128) NOT NULL COMMENT '活动链接',
  `start_time` datetime NOT NULL COMMENT '开始时间',
  `end_time` datetime NOT NULL COMMENT '结束时间',
  `day_num` int(6) NOT NULL COMMENT '天数',
  `remark` text NOT NULL COMMENT '介绍',
  `status` tinyint(3) NOT NULL COMMENT '状态 0禁用 1启用',
  `deal_status` tinyint(3) NOT NULL DEFAULT 0 COMMENT '活动状态 0未开始 1进行中 2活动结束待确认 3已确认待发奖励 4已结束',
  `prize_status` tinyint(4) NOT NULL DEFAULT 0 COMMENT '奖励发放状态 0未发放 1已发放',
  `rank_num` int(10) NOT NULL COMMENT '排名数量',
  `fake_num` int(10) NOT NULL COMMENT '马甲用户数量',
  `exec_interval` int(10) NOT NULL DEFAULT 3600 COMMENT '执行间隔秒',
  `first_exec_interval` int(4) NOT NULL DEFAULT 60 COMMENT '第一次执行间隔 单位分钟',
  `last_exec_time` datetime DEFAULT NULL COMMENT '上次执行时间',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `create_user` int(10) NOT NULL COMMENT '创建人',
  `update_time` datetime NOT NULL DEFAULT '0000-00-00 00:00:00' ON UPDATE current_timestamp() COMMENT '修改时间',
  `update_user` int(10) NOT NULL COMMENT '修改人',
  `brand_id` tinyint(3) NOT NULL DEFAULT 1 COMMENT '平台ID'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC;

-- --------------------------------------------------------

--
-- Table structure for table `yh_rank_activity_config`
--

CREATE TABLE `yh_rank_activity_config` (
  `id` int(10) UNSIGNED NOT NULL COMMENT 'ID',
  `activity_id` int(10) NOT NULL COMMENT '活动ID',
  `rank` int(6) NOT NULL COMMENT '排名',
  `reward_type` varchar(16) NOT NULL COMMENT '奖励类型 points积分 coupon优惠码 cash现金 product实物',
  `reward_condition` decimal(10,2) NOT NULL COMMENT '需要达到条件',
  `reward_value` varchar(32) NOT NULL COMMENT '返利',
  `image` varchar(255) NOT NULL COMMENT '图片',
  `step` int(4) NOT NULL COMMENT '当前等阶',
  `brand_id` tinyint(3) NOT NULL DEFAULT 1 COMMENT '平台ID'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC;

-- --------------------------------------------------------

