CREATE TABLE `yh_rank_activity_rate` (
  `id` int(10) NOT NULL COMMENT '主键',
  `activity_id` int(10) NOT NULL COMMENT '活动ID',
  `country_id` int(10) NOT NULL COMMENT '国家ID',
  `currency_symbol` varchar(16) NOT NULL COMMENT '货币符号',
  `rate` decimal(10,2) NOT NULL COMMENT '汇率'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC;

-- --------------------------------------------------------

--
-- Table structure for table `yh_rank_record`
--

CREATE TABLE `yh_rank_record` (
  `id` int(10) UNSIGNED NOT NULL COMMENT 'ID',
  `activity_id` int(10) NOT NULL COMMENT '活动ID',
  `country_id` int(10) NOT NULL COMMENT '国家ID',
  `user_id` int(10) NOT NULL COMMENT '用户ID',
  `username` varchar(64) NOT NULL COMMENT '用户名',
  `user_type` tinyint(3) NOT NULL COMMENT '用户类型 1真实用户 2马甲用户',
  `rank` int(6) NOT NULL COMMENT '排名',
  `reward_type` varchar(16) NOT NULL DEFAULT '' COMMENT '奖励类型 points积分 coupon优惠码 cash现金 product实物',
  `reward_value` varchar(32) NOT NULL DEFAULT '' COMMENT '奖励值',
  `amount` decimal(14,6) NOT NULL COMMENT '订单金额',
  `day_index` varchar(32) DEFAULT NULL COMMENT '当前天数/总天数',
  `day_condition` decimal(10,2) DEFAULT NULL COMMENT '当前条件',
  `reward_condition` decimal(10,2) DEFAULT NULL COMMENT '总条件',
  `create_time` int(10) UNSIGNED NOT NULL COMMENT '创建时间',
  `status` tinyint(3) NOT NULL DEFAULT 0 COMMENT '奖励状态 0初始状态，只有确认发放奖励才会进入后面的状态 1待领取奖励 2已领取奖励',
  `draw_time` int(10) NOT NULL DEFAULT 0 COMMENT '奖励领取时间'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC;

-- --------------------------------------------------------

