--
-- Table structure for table `yh_rebate_log`
--

CREATE TABLE `yh_rebate_log` (
  `id` int(10) UNSIGNED NOT NULL,
  `user_id` int(10) UNSIGNED NOT NULL COMMENT '用户ID',
  `activity_code` varchar(64) NOT NULL DEFAULT '' COMMENT '返利活动代码',
  `money` decimal(10,2) UNSIGNED NOT NULL COMMENT '返利金额',
  `order_no` varchar(64) NOT NULL DEFAULT '' COMMENT '关联订单号',
  `memo` varchar(512) NOT NULL DEFAULT '' COMMENT '其他备注',
  `freeze_status` tinyint(3) UNSIGNED NOT NULL DEFAULT 1 COMMENT '解冻状态1.待解冻 2.已解冻',
  `freeze_time` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '冻结到期时间',
  `freeze_out_time` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '执行解冻时间',
  `create_time` int(10) UNSIGNED NOT NULL COMMENT '创建时间',
  `brand_id` tinyint(3) UNSIGNED NOT NULL DEFAULT 1 COMMENT '品牌id',
  `wallet_type` tinyint(3) NOT NULL DEFAULT 1 COMMENT '钱包类型'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='返利详细记录表' ROW_FORMAT=DYNAMIC;

