  `type` tinyint(3) UNSIGNED NOT NULL COMMENT '类型：1.首单返利 2.推荐返利 3.注册返利 4.划转返利 5.满额返利 6.VIP返利',
  `vip_rate` decimal(10,2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT 'VIP返利率',
