  `title` varchar(64) NOT NULL DEFAULT '' COMMENT '标题',
  `message` varchar(512) NOT NULL COMMENT '消息，如果有参数，应该未{0},{1},{2}这种，用于替换',
  `notice_code` varchar(32) NOT NULL DEFAULT '' COMMENT '消息类型，对应yh_user_msg表',
  `push_code` varchar(32) NOT NULL DEFAULT '' COMMENT 'firebase推送跳转code',
  `email_template` varchar(32) NOT NULL DEFAULT '' COMMENT '邮件模板，有模板才会发邮件',
  `pop_id` varchar(10) NOT NULL DEFAULT '' COMMENT '弹窗ID，有ID代表有弹窗消息',
  `sms_status` tinyint(3) NOT NULL DEFAULT 0 COMMENT '0不发送短信 1发送短信',
  `remark` varchar(255) NOT NULL DEFAULT '' COMMENT '描述',
  `type` tinyint(3) NOT NULL DEFAULT 1 COMMENT '类型 1通知消息 2错误消息',
  `status` tinyint(3) NOT NULL DEFAULT 1 COMMENT '状态 1启用 0未启用',
  `brand_id` tinyint(3) NOT NULL DEFAULT 1 COMMENT '平台'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC;

