  `order_no` varchar(64) NOT NULL DEFAULT '' COMMENT '订单号',
  `type` tinyint(3) UNSIGNED NOT NULL COMMENT '自动充值类型：1.待充值 2.充值成功 3.充值失败 4.没充 5.充值异常 6.充值中',
  `unit` varchar(50) NOT NULL DEFAULT '' COMMENT '充值货币符号',
  `region` varchar(255) NOT NULL DEFAULT '',
  `amount` decimal(10,2) NOT NULL DEFAULT 0.00,
  `memo` varchar(512) NOT NULL DEFAULT '' COMMENT '其他备注',
  `create_time` int(10) UNSIGNED NOT NULL COMMENT '创建时间',
  `img_id` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '卡密对应图片ID'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='卡密自动充值表' ROW_FORMAT=DYNAMIC;

