--
-- Table structure for table `yh_user`
--

CREATE TABLE `yh_user` (
  `id` int(10) UNSIGNED NOT NULL,
  `username` varchar(64) NOT NULL COMMENT '用户名',
  `nickname` varchar(64) NOT NULL DEFAULT '' COMMENT '昵称',
  `password` varchar(64) NOT NULL DEFAULT '' COMMENT '密码',
  `avatar` varchar(512) NOT NULL DEFAULT '' COMMENT '头像图像地址',
  `phone` varchar(30) NOT NULL DEFAULT '' COMMENT '电话',
  `email` varchar(256) NOT NULL DEFAULT '' COMMENT '邮箱',
  `email_verify` tinyint(4) NOT NULL DEFAULT 1 COMMENT '邮箱地址是否有效(默认为1,当aws返回554错误代码后标记为0)',
  `country_id` int(10) UNSIGNED NOT NULL COMMENT '所属国家',
  `channel_type` tinyint(3) UNSIGNED NOT NULL DEFAULT 1 COMMENT '注册渠道：1.APP注册 2.推广链接 3.PC网站 4.wap 5.线下whatsapp 6.官方whatsapp 7.IOS 8.安卓 21.传音广告包 31.代理商注册 32.导入',
  `money` decimal(10,2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '账户余额',
  `usd_money` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT 'USDT账户余额',
  `agent_freeze_money` decimal(10,2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '代理商冻结金额',
  `rebate_money` decimal(10,2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '返利余额',
  `usd_rebate_money` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT 'USDT返利金额',
  `freeze_money` decimal(10,2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '冻结金额',
  `vip_level` smallint(5) UNSIGNED NOT NULL DEFAULT 1 COMMENT 'VIP等级',
  `vip_exp` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT 'VIP经验值',
  `point` int(10) NOT NULL DEFAULT 0 COMMENT '用户积分',
  `recommend_code` varchar(20) NOT NULL DEFAULT '' COMMENT '推荐码',
  `is_firstorder` tinyint(3) UNSIGNED NOT NULL DEFAULT 1 COMMENT '是否首单用户1.是 2.否',
  `create_time` int(10) UNSIGNED NOT NULL COMMENT '创建时间',
  `is_delete` tinyint(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否删除 0，未删除 1.已删除',
  `birthday` varchar(50) NOT NULL DEFAULT '' COMMENT '用户生日',
  `update_username_time` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '更新用户名的时间',
  `user_type` tinyint(4) NOT NULL DEFAULT 0 COMMENT '用户类型：0默认，1回流用户，2流失用户，3睡眠用户，4新用户，5准新用户，',
  `user_kind` tinyint(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '0 真实 1 需求马甲用户 2评论马甲用户',
  `trade_num` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '交易次数',
  `trade_amount` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '交易额',
  `guarantee` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '保证金',
  `last_active_time` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '最后上线时间',
  `user_level` tinyint(4) NOT NULL DEFAULT 0 COMMENT '用户等级：0默认，1皇冠用户，2金牌用户，3银牌用户，4铜牌用户',
  `brand_id` tinyint(3) UNSIGNED NOT NULL DEFAULT 1 COMMENT '品牌id',
  `cu_id` int(11) NOT NULL DEFAULT 0 COMMENT '名片ID',
  `t_password` varchar(64) NOT NULL DEFAULT '' COMMENT '交易密码',
  `i_verify` tinyint(1) NOT NULL DEFAULT 1 COMMENT '1：未认证   1 :已验证',
  `verify_msg` varchar(300) NOT NULL DEFAULT '' COMMENT '验证描述',
  `is_risk` tinyint(3) NOT NULL DEFAULT 0 COMMENT '是否风险用户',
  `register_type` tinyint(2) NOT NULL DEFAULT 0 COMMENT '注册方式0默认 1邮箱 2WhatsApp 3手机'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='售卡用户表' ROW_FORMAT=DYNAMIC;

