--
-- Table structure for table `yh_user_security`
--

CREATE TABLE `yh_user_security` (
  `id` int(10) UNSIGNED NOT NULL,
  `user_id` int(10) UNSIGNED NOT NULL COMMENT '用户ID',
  `type` varchar(20) NOT NULL COMMENT '密保问题类型：family、hometow、friend',
  `answer` varchar(100) NOT NULL COMMENT '密保答案',
  `create_time` int(10) UNSIGNED NOT NULL COMMENT '创建时间',
  `brand_id` tinyint(3) UNSIGNED NOT NULL DEFAULT 1 COMMENT '品牌id'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='用户密保答案' ROW_FORMAT=DYNAMIC;

-- --------------------------------------------------------

--
-- Table structure for table `yh_user_signin`
--

CREATE TABLE `yh_user_signin` (
  `id` int(10) UNSIGNED NOT NULL,
  `user_id` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户id',
  `run_days` tinyint(3) UNSIGNED NOT NULL DEFAULT 1 COMMENT '连续签到天数 0为首次签到',
  `reward_type` tinyint(3) UNSIGNED NOT NULL DEFAULT 1 COMMENT '签到活动奖励类型 1经验值 2 money',
  `reward_amount` int(10) UNSIGNED DEFAULT 0 COMMENT '奖励数量',
  `create_day` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建日期-天',
  `create_time` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建时间',
  `brand_id` tinyint(3) UNSIGNED NOT NULL DEFAULT 1 COMMENT '品牌id'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='用户签到表' ROW_FORMAT=DYNAMIC;

-- --------------------------------------------------------

--
-- Table structure for table `yh_user_subscribe`
--

CREATE TABLE `yh_user_subscribe` (
  `id` int(10) UNSIGNED NOT NULL,
  `user_id` int(11) NOT NULL COMMENT '用户ID',
  `country_id` int(11) DEFAULT NULL COMMENT '国家id',
  `category_id` int(11) NOT NULL COMMENT '订阅的卡种类ID',
  `card_id` int(11) NOT NULL DEFAULT 0 COMMENT '订阅的卡片ID，老的订阅只支持卡种类的订阅',
  `status` tinyint(1) NOT NULL COMMENT '订阅状态：1 订阅，2 取消',
  `subscribe_type` tinyint(3) NOT NULL DEFAULT 1 COMMENT '订阅类型 1 卡片种类订阅 2自定义订阅',
  `subscribe_rate` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '订阅的汇率，老的订阅汇率默认为0',
  `create_time` int(11) NOT NULL COMMENT '订阅时间',
  `brand_id` tinyint(3) UNSIGNED NOT NULL DEFAULT 1 COMMENT '品牌id',
  `notify_type` set('system','email','firebase','sms') NOT NULL DEFAULT 'system' COMMENT '通知类型 老的订阅不读这个配置'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='用户订阅卡种类表' ROW_FORMAT=DYNAMIC;

-- --------------------------------------------------------

--
-- Table structure for table `yh_user_token`
--

CREATE TABLE `yh_user_token` (
  `id` int(10) UNSIGNED NOT NULL,
  `user_id` int(10) UNSIGNED NOT NULL COMMENT '用户ID',
  `token` varchar(64) NOT NULL COMMENT 'TOKEN字符串',
  `expire_time` int(10) UNSIGNED NOT NULL COMMENT '到期时间',
  `create_time` int(10) UNSIGNED NOT NULL COMMENT '创建时间',
  `brand_id` tinyint(3) UNSIGNED NOT NULL DEFAULT 1 COMMENT '品牌id'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='用户TOKEN表' ROW_FORMAT=DYNAMIC;

