--
-- Table structure for table `yh_whatsapp`
--

CREATE TABLE `yh_whatsapp` (
  `id` int(11) NOT NULL,
  `brand_id` int(11) NOT NULL DEFAULT 0,
  `business_phone` varchar(50) NOT NULL DEFAULT '',
  `app_key` varchar(200) NOT NULL DEFAULT '',
  `template_name` varchar(200) NOT NULL DEFAULT '',
  `provider` varchar(200) NOT NULL DEFAULT '',
  `status` tinyint(1) NOT NULL DEFAULT 1
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='平台Whatsapp配置' ROW_FORMAT=DYNAMIC;

