--
-- Table structure for table `yh_whatsapp_code`
--

CREATE TABLE `yh_whatsapp_code` (
  `id` int(10) UNSIGNED NOT NULL,
  `user_id` int(11) NOT NULL DEFAULT 0 COMMENT '用户ID',
  `code` varchar(20) NOT NULL DEFAULT ' ' COMMENT '用户whatsapp验证code',
  `expiration_time` int(11) NOT NULL DEFAULT 0 COMMENT 'code过期时间',
  `create_time` int(11) NOT NULL DEFAULT 0 COMMENT '创建时间',
  `whatsapp` varchar(20) NOT NULL DEFAULT '' COMMENT 'whatsapp账号',
  `type` tinyint(3) NOT NULL DEFAULT 1 COMMENT '验证码用途 1注册2找回密码'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

