--
-- Table structure for table `yh_whatsapp_log`
--

CREATE TABLE `yh_whatsapp_log` (
  `id` int(10) UNSIGNED NOT NULL,
  `from` varchar(50) NOT NULL DEFAULT ' ' COMMENT '消息来源',
  `to` varchar(50) NOT NULL DEFAULT ' ' COMMENT '接受对象',
  `template_name` varchar(255) NOT NULL DEFAULT ' ' COMMENT '模板名称',
  `content` text NOT NULL COMMENT '消息内容',
  `message_type` tinyint(1) NOT NULL DEFAULT 1 COMMENT '消息类型：1 text, 2 模板',
  `type` tinyint(1) NOT NULL DEFAULT 0 COMMENT '规则类型：1出站 2入站 ',
  `create_time` int(11) NOT NULL DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

