--
-- Table structure for table `yh_withdraw_business`
--

CREATE TABLE `yh_withdraw_business` (
  `id` int(10) UNSIGNED NOT NULL COMMENT '转账接口ID',
  `business_code` varchar(32) DEFAULT NULL COMMENT '转账接口编码',
  `business_name` varchar(64) DEFAULT NULL COMMENT '转账接口名称',
  `desc` varchar(255) DEFAULT NULL COMMENT '描述',
  `is_default` tinyint(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否默认接口',
  `status` tinyint(3) UNSIGNED NOT NULL DEFAULT 1 COMMENT '1 开启 0 关闭',
  `bank_column` varchar(32) NOT NULL COMMENT '银行代码对应列',
  `is_delete` tinyint(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '1 删除 0 当前使用'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

