--
-- Table structure for table `yh_withdraw_config`
--

CREATE TABLE `yh_withdraw_config` (
  `id` int(10) UNSIGNED NOT NULL COMMENT '自增id',
  `country_id` int(11) NOT NULL COMMENT '国家',
  `single_amount` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '单笔限额',
  `daily_amount` int(10) UNSIGNED NOT NULL COMMENT '日限额',
  `daily_times` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '日提现次数',
  `monthly_amount` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '月限额',
  `type` tinyint(3) NOT NULL DEFAULT 1 COMMENT '1 银行卡 2 USDT',
  `brand_id` tinyint(3) UNSIGNED NOT NULL DEFAULT 1 COMMENT '品牌id'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='转账配置表' ROW_FORMAT=DYNAMIC;

