-- Table structure for table `yh_withdraw_log`
--

CREATE TABLE `yh_withdraw_log` (
  `id` int(10) UNSIGNED NOT NULL,
  `withdraw_no` varchar(64) NOT NULL,
  `memo` varchar(255) NOT NULL,
  `create_time` int(10) UNSIGNED NOT NULL,
  `user_id` int(10) UNSIGNED NOT NULL,
  `is_risk` tinyint(3) UNSIGNED DEFAULT 0 COMMENT '0 正常日志 1风险信息,阻碍流程',
  `business_id` int(10) NOT NULL DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

-- --------------------------------------------------------

--
-- Table structure for table `yh_withdraw_order`
--

CREATE TABLE `yh_withdraw_order` (
  `id` int(10) UNSIGNED NOT NULL,
  `country_id` int(10) UNSIGNED NOT NULL COMMENT '国家ID',
  `withdraw_no` varchar(64) NOT NULL DEFAULT '' COMMENT '提现流水号',
  `order_no` varchar(64) NOT NULL DEFAULT '' COMMENT '关联后台充值订单号',
  `user_id` int(10) UNSIGNED NOT NULL COMMENT '用户ID',
  `bank_id` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '注意：这是银行种类ID',
  `account_name` varchar(64) NOT NULL COMMENT '收款人名称',
  `account_no` varchar(64) NOT NULL COMMENT '收款人帐号',
  `amount` decimal(10,2) UNSIGNED NOT NULL COMMENT '提现金额',
  `status` tinyint(3) UNSIGNED NOT NULL COMMENT '状态1.待处理 2.处理中 3.处理成功 4.处理失败',
  `channel_type` tinyint(1) NOT NULL DEFAULT 1 COMMENT '订单创建渠道：1 移动端创建，2 后台创建',
  `admin_id` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '提现处理人员',
  `deal_type` tinyint(3) UNSIGNED NOT NULL DEFAULT 2 COMMENT '处理方式 1 系统接口 2 人工',
  `deal_time` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '提现处理时间',
  `deal_memo` varchar(512) NOT NULL DEFAULT '' COMMENT '处理备注',
  `system_deal_time` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '系统自动处理完成转账时间',
  `system_deal_flag` tinyint(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '自动转账处理结果 1 成功 0 失败',
  `system_deal_demo` varchar(512) NOT NULL DEFAULT '' COMMENT '系统处理备注',
  `system_cnt` int(11) NOT NULL DEFAULT 0 COMMENT '接口转账次数',
  `images` varchar(1024) NOT NULL DEFAULT '' COMMENT '订单成功后提交的图片',
  `create_time` int(10) UNSIGNED NOT NULL COMMENT '创建时间',
  `brand_id` tinyint(3) UNSIGNED NOT NULL DEFAULT 1 COMMENT '品牌id',
  `crm_notice` int(11) NOT NULL DEFAULT 1 COMMENT 'crm 订单处理通知：1 未通知，2 已通知',
  `user_bank` varchar(64) NOT NULL DEFAULT '' COMMENT '收款人银行',
  `wallet_type` tinyint(3) NOT NULL DEFAULT 1 COMMENT '钱包类型 1 国家货币 2 USDT',
  `payment_id` int(10) UNSIGNED NOT NULL DEFAULT 1,
  `paybill_no` varchar(64) DEFAULT NULL,
  `business_id` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '0:人工 1:3ph 2:goodnews 3:onedot',
  `is_audit` tinyint(3) UNSIGNED DEFAULT 0 COMMENT '0:非审核 1:人工审核',
  `is_compensated` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否超时赔付 1赔付 0未赔付'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='提现请求表' ROW_FORMAT=DYNAMIC;

-- --------------------------------------------------------

