CREATE TABLE `yh_withdraw_payin` (
  `id` int(10) UNSIGNED NOT NULL COMMENT 'ID',
  `amount` decimal(10,2) DEFAULT NULL COMMENT '金额',
  `narration` varchar(255) DEFAULT NULL,
  `session_id` varchar(255) DEFAULT NULL,
  `remit_reference` varchar(255) DEFAULT NULL,
  `business_id` tinyint(3) DEFAULT NULL,
  `create_time` int(10) UNSIGNED DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC;

-- --------------------------------------------------------

--
-- Table structure for table `yh_withdraw_sys_log`
--

CREATE TABLE `yh_withdraw_sys_log` (
  `id` int(10) UNSIGNED NOT NULL COMMENT 'id',
  `withdraw_no` varchar(200) NOT NULL DEFAULT '' COMMENT '提现订单号',
  `status` varchar(20) NOT NULL DEFAULT '' COMMENT '当前状态 init listen success failed reversed',
  `bank_code` varchar(20) NOT NULL DEFAULT '' COMMENT '银行代码',
  `account_number` varchar(50) NOT NULL DEFAULT '' COMMENT '银行卡号码',
  `account_name` varchar(50) NOT NULL DEFAULT '' COMMENT '户名',
  `recipient_code` varchar(50) NOT NULL DEFAULT '' COMMENT '收款人凭据',
  `trans_id` varchar(100) NOT NULL DEFAULT '' COMMENT '第三方交易id',
  `transfer_code` varchar(200) NOT NULL DEFAULT '' COMMENT '第三方交易凭证',
  `memo` varchar(2048) NOT NULL DEFAULT '' COMMENT '备注',
  `update_time` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '更新时间',
  `create_time` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '创建时间',
  `brand_id` tinyint(3) UNSIGNED NOT NULL DEFAULT 1 COMMENT '品牌id'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='提现系统转账日志表' ROW_FORMAT=DYNAMIC;

